use super::{native_appearance_continuation_study as c,native_appearance_clock_study as clock,native_appearance_inspection as a,sprite};
use std::{fs,path::{Path,PathBuf},collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn ordinary()->clock::OrdinaryInputs{clock::OrdinaryInputs{ordinary_branch_reached:Some(true),player_global:Some(20000),queue_after_pop:Some(0),modifier_1c:Some(0),modifier_21:Some(0),action21_counter:Some(0),catalog_scaling_disabled:Some(true),frozen_external_state:Some(true),sampled_clock_ms:Some(1000)}}
fn end()->c::EndInputs{c::EndInputs{queue_after_end:Some(0),render_player_pointer_equal:Some(false),actor_50_counter:Some(0),base_action:Some(46),idle_table_pointer_present:Some(true),queue_append_succeeds:Some(true)}}
struct Fixed{root:PathBuf,pins:BTreeMap<String,Value>}
impl Fixed{fn new()->Self{let p:Value=serde_json::from_slice(&fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r439-appearance-snapshot.json")).unwrap()).unwrap();let root=PathBuf::from(p["candidate"]["root"].as_str().unwrap());let bytes=fs::read(root.join("manifest.json")).unwrap();assert_eq!(sha(&bytes),p["candidate"]["manifest_sha256"].as_str().unwrap().to_ascii_lowercase());let m:Value=serde_json::from_slice(&bytes).unwrap();Self{root,pins:m["files"].as_array().unwrap().iter().map(|v|(v["path"].as_str().unwrap().to_string(),v.clone())).collect()}}fn bytes(&self,name:&str)->Vec<u8>{let p=&self.pins[name];let bytes=fs::read(self.root.join(name)).unwrap();assert_eq!(bytes.len()as u64,p["bytes"].as_u64().unwrap());assert_eq!(sha(&bytes),p["sha256"].as_str().unwrap().to_ascii_lowercase());bytes}}
#[test]#[ignore = "requires: local evidence roots (snapshot JSON holds absolute D:\\ paths + SHA pins; only runnable on the original machine)"] fn actual_attack47_continuation_end_idle_queue_and_late_callback_CPU(){
 let fixed=Fixed::new();let d=a::nad(&fixed.bytes("resources/appearance-dependencies.nad")).unwrap();let owners=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&owners[3];let mut rows=Vec::new();
 for heading in 0..8{let mut m=c::Model::new(true,&d,b,b,b.observed,heading,ordinary(),end()).unwrap();let mut due=1168;for frame in [2,3,4,5,6,0]{assert_eq!(m.due(b,b.observed).unwrap(),due);let step=m.advance(b,b.observed,due).unwrap();assert_eq!(step.frame,frame);assert!(!step.renderer_ready&&!step.events_dispatched&&!step.visible_residency_qualified);if frame==0{assert!(step.ended&&step.study_stopped);assert_eq!(step.next_action_queued,Some(49));assert_eq!(step.returned_duration_ms,83);assert_eq!(step.next_delay_ms,584);assert!(m.advance(b,b.observed,step.next_due_ms).is_err());}else{assert!(!step.ended&&step.next_action_queued.is_none());assert_eq!(step.next_delay_ms,step.returned_duration_ms+2);}rows.push(json!({"heading":heading,"action":step.action,"frame":frame,"dispatch_ms":step.dispatch_ms,"previous_expected_ms":step.previous_expected_ms,"returned_ms":step.returned_duration_ms,"delay_ms":step.next_delay_ms,"next_due_ms":step.next_due_ms,"queued_action":step.next_action_queued,"ended":step.ended,"member":step.member.name,"subframe":step.catalog.subframe,"events_hex":step.catalog.events.iter().map(|b|format!("{b:02x}")).collect::<String>()}));due=step.next_due_ms;}}
 let mut late=c::Model::new(true,&d,b,b,b.observed,0,ordinary(),end()).unwrap();let due=late.due(b,b.observed).unwrap();let s=late.advance(b,b.observed,due+30).unwrap();assert_eq!(s.frame,2);assert_eq!(s.returned_duration_ms,166);assert_eq!(s.next_delay_ms,138);assert_eq!(s.next_due_ms,due+168);let s=late.advance(b,b.observed,due+168+1000).unwrap();assert_eq!(s.next_delay_ms,3);assert_eq!(late.due(b,b.observed).unwrap(),2339);late.retire();assert!(late.due(b,b.observed).is_err());
 for selector in 0..7{let mut e=end();match selector{0=>e.queue_after_end=None,1=>e.render_player_pointer_equal=Some(true),2=>e.actor_50_counter=Some(1),3=>e.base_action=Some(0),4=>e.idle_table_pointer_present=None,5=>e.queue_append_succeeds=None,_=>e.queue_append_succeeds=Some(false)};assert!(c::Model::new(true,&d,b,b,b.observed,0,ordinary(),e).is_err());}
 assert!(c::Model::new(false,&d,b,b,b.observed,0,ordinary(),end()).is_err());let mut m=c::Model::new(true,&d,b,b,b.observed,0,ordinary(),end()).unwrap();assert!(m.advance(b,b.observed,1167).is_err());let mut wrong=b.clone();wrong.revision+=1;assert!(m.due(&wrong,b.observed).is_err());let mut zero=d.clone();zero.rows.get_mut(&734).unwrap().actions.get_mut(&47).unwrap().frames[2].ticks=0;let mut m=c::Model::new(true,&zero,b,b,b.observed,0,ordinary(),end()).unwrap();assert!(m.advance(b,b.observed,1168).is_err());
 // Actual selected body frames in a finite contact strip; no visible residence claim.
 let plan=a::plan(true,&d,b,b,b.observed,a::Kind::Attack,0,128).unwrap();let mut cache=BTreeMap::new();let mut members=BTreeMap::new();let mut samples=Vec::new();let cell=180usize;let width=7*cell;let mut rgba=vec![0u8;width*cell*4];for y in 0..cell{for x in 0..width{rgba[(y*width+x)*4..(y*width+x+1)*4].copy_from_slice(if(x/10+y/10)%2==0{&[32,35,40,255]}else{&[40,43,48,255]});}}
 for(column,index)in [1,2,3,4,5,6,0].iter().enumerate(){let(catalog,member)=plan.frames[*index];if !cache.contains_key(&member.name){let bytes=fixed.bytes(&format!("resources/{}",member.name));assert_eq!(<[u8;32]>::from(Sha256::digest(&bytes)),member.sha256);let spr=sprite::decode_classic_spr_with_limits(bytes.strip_prefix(b"SPR_0").unwrap_or(&bytes),sprite::SpriteLimits{max_input_bytes:1024*1024,max_frames:255,max_blocks:8192,max_block_references:65536,max_frame_dimension:2048,max_total_pixels:4*1024*1024}).unwrap();assert_eq!(spr.frames.len(),member.frames as usize);members.insert(member.name.clone(),sha(&bytes));cache.insert(member.name.clone(),spr);}let frame=&cache[&member.name].frames[catalog.subframe as usize];assert!(frame.width as usize<=cell&&frame.height as usize<=cell);let x0=column*cell+(cell-frame.width as usize)/2;let y0=(cell-frame.height as usize)/2;for y in 0..frame.height as usize{for x in 0..frame.width as usize{let src=&frame.rgba[(y*frame.width as usize+x)*4..(y*frame.width as usize+x+1)*4];let dst=((y0+y)*width+x0+x)*4;for channel in 0..3{rgba[dst+channel]=((u32::from(src[channel])*u32::from(src[3])+u32::from(rgba[dst+channel])*(255-u32::from(src[3]))+127)/255)as u8;}}}samples.push(json!({"frame":index,"member":member.name,"subframe":catalog.subframe,"source_offset":[frame.x_offset,frame.y_offset],"size":[frame.width,frame.height]}));}
 let out=Path::new(env!("CARGO_MANIFEST_DIR")).join("target/r447-appearance-continuation-cpu");fs::create_dir_all(&out).unwrap();let image=out.join("elf-attack47-first1-continue2to6-end0.png");let mut enc=png::Encoder::new(fs::File::create(&image).unwrap(),width as u32,cell as u32);enc.set_color(png::ColorType::Rgba);enc.set_depth(png::BitDepth::Eight);enc.write_header().unwrap().write_image_data(&rgba).unwrap();
 fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r447-continuation-details.json"),serde_json::to_vec_pretty(&json!({"state":"FINITE_CONDITIONAL_ATTACK47_CONTINUATION_END_QUEUED_IDLE49_STOP","source":b.source,"object":b.object,"epoch_hex":format!("{:016x}",b.epoch),"revision":b.revision,"rows":rows,"late_callback_cases":2,"image":{"path":image,"sha256":sha(&fs::read(&image).unwrap()),"RGBA_sha256":sha(&rgba),"dimensions":[width,cell],"samples":samples},"member_pins":members,"runtime_inputs_observed":false,"queued_idle_callback_executed":false,"events_dispatched":false,"visible_residency_qualified":false,"natural_loop_qualified":false,"renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();
}
